using System.Data; using Marina.Application.Commerce; using Marina.Domain.Catalog; using Marina.Domain.Commerce; using Marina.Persistence.Data; using Microsoft.EntityFrameworkCore;
namespace Marina.Persistence.Commerce;
public sealed class CommerceRepository(MarinaDbContext db):ICommerceRepository{public Task<Order?>FindOrderByIdempotencyAsync(Guid userId,string key,CancellationToken ct)=>db.Orders.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.UserId==userId&&x.IdempotencyKey==key,ct);public Task<Address?>FindOwnedAddressAsync(Guid userId,Guid id,CancellationToken ct)=>db.Addresses.SingleOrDefaultAsync(x=>x.UserId==userId&&x.Id==id&&!x.IsDeleted,ct);public async Task<IReadOnlyDictionary<Guid,ProductVariant>>GetVariantsForCheckoutAsync(IEnumerable<Guid>ids,CancellationToken ct)=>await db.ProductVariants.Include(x=>x.Product).ThenInclude(x=>x.Translations).Include(x=>x.Inventory).Include(x=>x.Color!).ThenInclude(x=>x.Translations).Include(x=>x.Size!).ThenInclude(x=>x.Translations).Where(x=>ids.Contains(x.Id)&&x.IsActive&&!x.IsDeleted&&x.Product.IsActive&&!x.Product.IsDeleted&&x.Product.Category.IsActive&&!x.Product.Category.IsDeleted&&(x.Product.Brand==null||(x.Product.Brand.IsActive&&!x.Product.Brand.IsDeleted))&&x.Inventory!=null&&!x.Inventory.IsDeleted).ToDictionaryAsync(x=>x.Id,ct);public Task<Coupon?>FindCouponAsync(string code,CancellationToken ct)=>db.Coupons.SingleOrDefaultAsync(x=>x.Code==code&&!x.IsDeleted,ct);public Task<int>CouponUseCountAsync(Guid couponId,Guid?userId,CancellationToken ct)=>db.CouponUsages.CountAsync(x=>x.CouponId==couponId&&(!userId.HasValue||x.UserId==userId),ct);public Task ClearPurchasedCartAsync(Guid userId,IEnumerable<Guid> variantIds,CancellationToken ct)=>db.CartItems.Where(x=>x.Cart.UserId==userId&&variantIds.Contains(x.VariantId)).ExecuteDeleteAsync(ct);public void Add<T>(T entity)where T:class=>db.Add(entity);public async Task SaveAsync(CancellationToken ct)=>await db.SaveChangesAsync(ct);public async Task<T>InSerializableTransactionAsync<T>(Func<CancellationToken,Task<T>>operation,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var result=await operation(ct);await tx.CommitAsync(ct);return result;}}
